{"cmd":["Set-Content -Path 'fb_moving_average.st' -Value @'
FUNCTION_BLOCK FB_MovingAverage
VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR

VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error : BOOL;
    status : WORD;
END_VAR

VAR
    buffer : ARRAY[1..100] OF LREAL;
    index : INT := 1;
    count : INT := 0;
    sum : LREAL := 0.0;
    lastTrigger : BOOL := FALSE;
    i : INT;
END_VAR

(* Main logic *)
IF reset THEN
    (* Reset all internal state *)
    index := 1;
    count := 0;
    sum := 0.0;
    average := 0.0;
    windowSizeReached := FALSE;
    error := FALSE;
    status := 16#0000;

    (* Clear the buffer *)
    FOR i := 1 TO 100 DO
        buffer[i] := 0.0;
    END_FOR;

    lastTrigger := FALSE;

ELSIF windowSize < 1 OR windowSize > 100 THEN
    (* Window size validation error *)
    error := TRUE;
    status := 16#8200;
    windowSizeReached := FALSE;

ELSE
    (* Check for update condition: cyclic execution OR rising edge of trigger *)
    IF cyclicExecution OR (trigger AND NOT lastTrigger) THEN
        (* If buffer is full, subtract the oldest value from sum *)
        (* If buffer not full, just increment count *)
        IF count >= windowSize THEN
            sum := sum - buffer[index];
        ELSE
            count := count + 1;
        END_IF;

        (* Store new value and update sum *)
        buffer[index] := value;
        sum := sum + value;

        (* Calculate average *)
        average := sum / LREAL_TO_INT(count);

        (* Update circular buffer index (wrap around) *)
        index := (index MOD windowSize) + 1;

        (* Update windowSizeReached flag *)
        windowSizeReached := (count >= windowSize);

        (* Clear error status on successful execution *)
        error := FALSE;
        status := 16#0000;
    END_IF;

    (* Store trigger state for next cycle (rising edge detection) *)
    lastTrigger := trigger;
END_IF;

END_FUNCTION_BLOCK
'@"]}
